["Initialization"] = "function(modTable)\n    -- Last update: 28-11-2023\n    local default, affixes = \"#00fbff\", \"#C69B6D\"\n    \n    modTable.NpcColors = {\n        -- Affixes\n        [204560] = affixes, -- Incorporeal Being\n        -- Dawn of the Infinites: Galakrond's Fall [FALL]\n        [205384] = default, -- Infinite Chronoweaver\n        [206140] = default, -- Coalesced Time\n        [205804] = default, -- Risen Dragon\n        [205691] = default, -- Iridikron's Creation\n        -- Dawn of the Infinites: Murozond's Rise [RISE]\n        [205158] = default, -- Spurlok, Timesworn Sentinel\n        [205152] = default, -- Lerai, Timesworn Maiden\n        [206230] = default, -- Infinite Diversionist\n        [208698] = default, -- Infinite Riftmage\n        [205363] = default, -- Time-Lost Waveshaper\n        [208193] = default, -- Paladin of the Silver Hand\n        [208440] = default, -- Infinite Slayer\n        [205212] = default, -- Infinite Keeper\n        -- Darkheart Thicket [DHT]\n        [95771] = default, -- Dreadsoul Ruiner\n        [99359] = default, -- Rotheart Keeper\n        [100531] = default, -- Bloodtainted Fury\n        [99365] = default, -- Taintheart Stalker\n        -- Black Rook Hold [BRH]\n        [98362] = default, -- Troubled Soul\n        [98538] = default, -- Lady Velandras Ravencrest\n        [98521] = default, -- Lord Etheldrin Ravencrest\n        [98280] = default, -- Risen Arcanist\n        [101549] = default, -- Arcane Minion\n        [98810] = default, -- Wrathguard Bladelord\n        [102788] = default, -- Felspite Dominator\n        -- Waycrest Manor [WM]\n        [131677] = default, -- Heartsbane Runeweaver\n        [131586] = default, -- Banquet Steward\n        [131858] = default, -- Thornguard\n        [131685] = default, -- Runic Disciple\n        [131812] = default, -- Heartsbane Soulcharmer\n        -- Atal'Dazar [AD]\n        [127315] = default, -- Reanimation Totem\n        [122973] = default, -- Dazar'ai Confessor\n        [128434] = default, -- Feasting Skyscreamer\n        -- Everbloom [EB]\n        [81820] = default, -- Everbloom Mender\n        [81984] = default, -- Gnarlroot\n        [84767] = default, -- Twisted Abomination\n        [84957] = default, -- Putrid Pyromancer\n        -- Throne of the Tides [TOTT]\n        [41096] = default, -- Naz'jar Oracle\n        [214117] = default, -- Stormflurry Totem\n        [44404] = default, -- Naz'jar Frost Witch\n        [212775] = default, -- Faceless Seer\n        [40925] = default, -- Tainted Sentry\n    }\n    \n    function modTable.UpdateColor(unitFrame, envTable)\n        if not unitFrame or unitFrame.IsNpcWithoutHealthbar or unitFrame.IsFriendlyPlayerWithoutHealthbar then return end\n        -- Get color from modTable.NpcColors\n        local color = modTable.NpcColors [unitFrame.namePlateNpcId]\n        -- Set color from modTable.NpcColors\n        if (color) then\n            Plater.SetNameplateColor(unitFrame, color)\n        end\n    end\nend",
["Nameplate Updated"] = "function (self, unitId, unitFrame, envTable, modTable)\n    modTable.UpdateColor (unitFrame, envTable)\nend",
},
